    no_signal EXCEPTION (-20102, 'GATHER_EVIDENCE: the case holds no signal');  
    started TIMESTAMP_LTZ;
    run_at TIMESTAMP_NTZ;
    n INTEGER;
    v_party VARCHAR;
    anchor VARCHAR;
    party_ev VARCHAR;
    ev_before INTEGER;
