    logged INTEGER DEFAULT 0;
    ql_id VARCHAR;
    wrapped VARCHAR;
    rs RESULTSET;
    t0 TIMESTAMP_LTZ;
    snap VARIANT;
    ql_ms INTEGER;
    q_summary VARCHAR DEFAULT 'WITH p AS (SELECT ?::VARCHAR AS case_id),        
ids AS (
    SELECT DISTINCT f.value::VARCHAR AS txn_id
    FROM RISK_COPILOT_DEV.EVIDENCE_CHAIN.CASE_SIGNAL cs
    JOIN RISK_COPILOT_DEV.EVIDENCE_CHAIN.SIGNAL s ON s.signal_id = cs.signal_id,
    LATERAL FLATTEN(input => s.evidence_txn_ids) f
    WHERE cs.case_id = (SELECT case_id FROM p)
),
