  1|-- ===========================================================================
  2|-- procedures / 05_attest_str.sql
  3|-- ===========================================================================
  4|-- ATTEST_STR(artifact_id, decision, attestor, comment): the human gate.
  5|--
  6|-- Under PML Rule 7 (clause PRINCIPAL_OFFICER_ATTESTATION_REQUIRED) the
  7|-- Principal Officer bears the filing obligation, so no STR reaches FILED
  8|-- without a person signing this exact version. The rule is enforced here, in
  9|-- code, never by an instruction to a model:
 10|--
 11|--   * EXECUTE AS CALLER, and the caller's session must hold the compliance
 12|--     officer role -- the owner's role does not stand in for the caller's
 13|--   * the artifact must be REVIEWED, its latest review APPROVE, and the hash
 14|--     the Reviewer approved must equal the content's hash now; the signature
 15|--     records that hash, so a later edit is detectable
 16|--   * ATTESTED -> artifact FILED (a simulated FIU-IND submission), case CLOSED;
 17|--     RETURNED -> artifact RETURNED, case back to DRAFTED for a redraft
 18|--
 19|-- No other procedure sets FILED. A refusal is logged as REFUSED with its reason.
 20|-- ===========================================================================
 21|{% from "procedures/_macros.sql" import audit with context %}
 22|{% set T = tool %}
 23|{% set EV = fq.evidence %}
 24|
 25|CREATE OR REPLACE PROCEDURE {{ EV }}.{{ T.attest_str }}(
 26|    ARTIFACT_ID VARCHAR, DECISION VARCHAR, ATTESTOR VARCHAR, ATTEST_COMMENT VARCHAR DEFAULT NULL
 27|)
 28|    RETURNS VARIANT
 29|    LANGUAGE SQL
 30|    COMMENT = 'Human gate: Principal Officer attests or returns one REVIEWED STR. Caller rights; compliance role required.'
 31|    EXECUTE AS CALLER
 32|AS
 33|$$
 34|DECLARE
 35|    bad_decision EXCEPTION (-20131, 'ATTEST_STR: decision must be ATTESTED or RETURNED');
 36|    no_attestor EXCEPTION (-20132, 'ATTEST_STR: the attesting officer must be named');
 37|    wrong_role EXCEPTION (-20133, 'ATTEST_STR: only the compliance officer role may attest');
 38|    not_reviewed EXCEPTION (-20134, 'ATTEST_STR: only a REVIEWED artifact with an APPROVE review can be attested');
 39|    hash_changed EXCEPTION (-20135, 'ATTEST_STR: the artifact changed after review; re-review before attesting');
 40|    started TIMESTAMP_LTZ;
 41|    run_at TIMESTAMP_NTZ;
 42|    n INTEGER;
 43|    v_case VARCHAR;
 44|    fid VARCHAR;
 45|    v_status VARCHAR;
 46|    stored_hash VARCHAR;
 47|    actual_hash VARCHAR;
 48|    reviewed_hash VARCHAR;
 49|    last_decision VARCHAR;
 50|    att_id VARCHAR;
 51|    new_status VARCHAR;
 52|    err VARCHAR;
 53|BEGIN
 54|    started := CURRENT_TIMESTAMP();
 55|    fid := (SELECT MAX(finding_id) FROM {{ EV }}.ARTIFACT WHERE artifact_id = :artifact_id);
 56|    v_case := (SELECT MAX(case_id) FROM {{ EV }}.FINDING WHERE finding_id = :fid);
 57|    IF (decision IS NULL OR decision NOT IN ('ATTESTED', 'RETURNED')) THEN
 58|        RAISE bad_decision;
 59|    END IF;
 60|    IF (attestor IS NULL OR LENGTH(TRIM(attestor)) < 3) THEN
 61|        RAISE no_attestor;
 62|    END IF;
 63|    IF (NOT IS_ROLE_IN_SESSION('{{ role.compliance_officer }}')) THEN
 64|        RAISE wrong_role;
 65|    END IF;
 66|
 67|    v_status := (SELECT MAX(status) FROM {{ EV }}.ARTIFACT WHERE artifact_id = :artifact_id);
 68|    last_decision := (
 69|        SELECT MAX(decision) FROM (
 70|            SELECT decision FROM {{ EV }}.REVIEW WHERE finding_id = :fid
 71|            QUALIFY ROW_NUMBER() OVER (ORDER BY reviewed_at DESC, review_id DESC) = 1
 72|        )
 73|    );
 74|    IF (v_status IS DISTINCT FROM 'REVIEWED' OR last_decision IS DISTINCT FROM 'APPROVE') THEN
 75|        RAISE not_reviewed;
 76|    END IF;
 77|    stored_hash := (SELECT MAX(content_hash) FROM {{ EV }}.ARTIFACT WHERE artifact_id = :artifact_id);
 78|    actual_hash := (SELECT MAX(SHA2(TO_JSON(content), 256)) FROM {{ EV }}.ARTIFACT WHERE artifact_id = :artifact_id);
 79|    reviewed_hash := (
 80|        SELECT MAX(checks_run:content_hash::VARCHAR) FROM (
 81|            SELECT checks_run FROM {{ EV }}.REVIEW WHERE finding_id = :fid
 82|            QUALIFY ROW_NUMBER() OVER (ORDER BY reviewed_at DESC, review_id DESC) = 1
 83|        )
 84|    );
 85|    IF (stored_hash IS DISTINCT FROM actual_hash OR reviewed_hash IS DISTINCT FROM actual_hash) THEN
 86|        RAISE hash_changed;
 87|    END IF;
 88|
 89|    BEGIN TRANSACTION;
 90|    run_at := CURRENT_TIMESTAMP()::TIMESTAMP_NTZ;
 91|    n := (SELECT COUNT(*) FROM {{ EV }}.ATTESTATION WHERE artifact_id = :artifact_id);
 92|    att_id := 'ATT-' || LEFT(SHA2(artifact_id || '|' || TO_VARCHAR(n + 1), 256), 16);
 93|    INSERT INTO {{ EV }}.ATTESTATION (
 94|        attestation_id, artifact_id, attested_content_hash, attestor, attestor_role, decision, comment
 95|    )
 96|    SELECT :att_id, :artifact_id, :actual_hash, TRIM(:attestor), 'PRINCIPAL_OFFICER', :decision, :attest_comment;
 97|
 98|    new_status := IFF(decision = 'ATTESTED', 'FILED', 'RETURNED');
 99|    UPDATE {{ EV }}.ARTIFACT SET status = :new_status WHERE artifact_id = :artifact_id;
100|    UPDATE {{ EV }}.CASE_RECORD
101|    SET status = IFF(:decision = 'ATTESTED', 'CLOSED', 'DRAFTED'),
102|        closed_at = IFF(:decision = 'ATTESTED', :run_at, NULL),
103|        closure_reason = IFF(:decision = 'ATTESTED', 'STR_FILED', NULL),
104|        updated_at = :run_at
105|    WHERE case_id = :v_case;
106|
107|    {{ audit("REVIEWER", T.attest_str, "OBJECT_CONSTRUCT('artifact_id', :artifact_id, 'decision', :decision, 'attestor', :attestor)", "SUCCESS",
108|             "'HUMAN'", "'n/a'", case_var="v_case") }};
109|    COMMIT;
110|    RETURN OBJECT_CONSTRUCT(
111|        'attestation_id', att_id,
112|        'artifact_id', artifact_id,
113|        'artifact_status', new_status,
114|        'attested_content_hash', actual_hash,
115|        'decision', decision
116|    );
117|EXCEPTION
118|    WHEN OTHER THEN
119|        ROLLBACK;
120|        err := SQLERRM;
121|        -- The refusal itself is evidence: record who tried and why it failed.
122|        {{ audit("REVIEWER", T.attest_str, "OBJECT_CONSTRUCT('artifact_id', :artifact_id, 'decision', :decision, 'attestor', :attestor)", "REFUSED",
123|                 "'HUMAN'", "'n/a'", error=":err", case_var="v_case") }};
124|        RAISE;
125|END;
126|$$;
