  1|-- ===========================================================================
  2|-- 00_bootstrap / 02_roles_grants.sql
  3|-- ===========================================================================
  4|-- Role hierarchy and grants.
  5|--
  6|-- Requires a role that can create roles (ACCOUNTADMIN or a delegate). If the
  7|-- deploying principal cannot, this file fails first and nothing else is
  8|-- half-created.
  9|--
 10|-- Design note on least privilege: the branch analyst roles get SELECT only.
 11|-- They are the subjects of the row-access-policy demo, so granting them write
 12|-- access anywhere would undermine the very claim being demonstrated.
 13|-- ===========================================================================
 14|
 15|USE ROLE ACCOUNTADMIN;
 16|
 17|-- --------------------------------------------------------------------------
 18|-- Roles
 19|-- --------------------------------------------------------------------------
 20|CREATE ROLE IF NOT EXISTS {{ role.admin }}
 21|    COMMENT = 'Owns all Risk Copilot objects ({{ profile }}).';
 22|
 23|CREATE ROLE IF NOT EXISTS {{ role.service }}
 24|    COMMENT = 'Used by Cortex agents and scheduled automations. Never a human.';
 25|
 26|CREATE ROLE IF NOT EXISTS {{ role.compliance_officer }}
 27|    COMMENT = 'Sees all data; the only role permitted to attest an artifact.';
 28|
 29|{% for region, analyst_role in role.branch_analysts.items() %}
 30|CREATE ROLE IF NOT EXISTS {{ analyst_role }}
 31|    COMMENT = 'Branch analyst restricted to branch_region = {{ region }} by row access policy.';
 32|{% endfor %}
 33|
 34|-- --------------------------------------------------------------------------
 35|-- Hierarchy.  Inheritance runs upward: ACCOUNTADMIN sees everything
 36|-- {{ role.admin }} can see, which is what keeps the account auditable.
 37|-- --------------------------------------------------------------------------
 38|GRANT ROLE {{ role.admin }} TO ROLE ACCOUNTADMIN;
 39|GRANT ROLE {{ role.service }} TO ROLE {{ role.admin }};
 40|GRANT ROLE {{ role.compliance_officer }} TO ROLE {{ role.admin }};
 41|{% for region, analyst_role in role.branch_analysts.items() %}
 42|GRANT ROLE {{ analyst_role }} TO ROLE {{ role.admin }};
 43|{% endfor %}
 44|
 45|-- The deploying user needs the admin role to apply every later stage.
 46|-- GRANT ROLE ... TO USER takes a literal identifier and rejects IDENTIFIER(),
 47|-- so the user name is resolved at run time and the grant issued as dynamic SQL.
 48|-- Quoted, because a user name is not guaranteed to be a bare identifier.
 49|EXECUTE IMMEDIATE $$
 50|BEGIN
 51|    LET deploying_user STRING := CURRENT_USER();
 52|    EXECUTE IMMEDIATE 'GRANT ROLE {{ role.admin }} TO USER "' || deploying_user || '"';
 53|    RETURN 'granted {{ role.admin }} to ' || deploying_user;
 54|END;
 55|$$;
 56|
 57|-- --------------------------------------------------------------------------
 58|-- Warehouse privileges
 59|-- --------------------------------------------------------------------------
 60|GRANT USAGE ON WAREHOUSE {{ wh.dev }} TO ROLE {{ role.admin }};
 61|GRANT OPERATE, USAGE ON WAREHOUSE {{ wh.pipeline }} TO ROLE {{ role.admin }};
 62|GRANT USAGE ON WAREHOUSE {{ wh.pipeline }} TO ROLE {{ role.service }};
 63|GRANT USAGE ON WAREHOUSE {{ wh.demo }} TO ROLE {{ role.service }};
 64|GRANT USAGE ON WAREHOUSE {{ wh.demo }} TO ROLE {{ role.compliance_officer }};
 65|{% for region, analyst_role in role.branch_analysts.items() %}
 66|GRANT USAGE ON WAREHOUSE {{ wh.demo }} TO ROLE {{ analyst_role }};
 67|{% endfor %}
 68|
 69|-- --------------------------------------------------------------------------
 70|-- Ownership.  The admin role owns everything, so object ownership does not
 71|-- follow whichever human happened to run the deploy.
 72|-- --------------------------------------------------------------------------
 73|GRANT OWNERSHIP ON DATABASE {{ db }} TO ROLE {{ role.admin }} COPY CURRENT GRANTS;
 74|{% for key in ['raw', 'curated', 'governance', 'evidence', 'audit', 'ground_truth', 'ml'] %}
 75|GRANT OWNERSHIP ON SCHEMA {{ fq[key] }} TO ROLE {{ role.admin }} COPY CURRENT GRANTS;
 76|{% endfor %}
 77|
 78|-- Stages and file formats too. 01_account_objects.sql creates them as
 79|-- ACCOUNTADMIN, and ownership of a schema does not carry to the objects inside
 80|-- it: measured on the dev account, all four stages and all four file formats
 81|-- were still owned by ACCOUNTADMIN, so the admin role could PUT to a stage only
 82|-- through a human session's secondary roles -- never from a task (build log M27).
 83|{% for schema_key, stage_key in [('raw', 'data'), ('raw', 'generated'), ('governance', 'policy_docs'), ('governance', 'scripts'), ('ground_truth', 'ground_truth')] %}
 84|GRANT OWNERSHIP ON STAGE {{ fq[schema_key] }}.{{ stage[stage_key] }} TO ROLE {{ role.admin }} COPY CURRENT GRANTS;
 85|{% endfor %}
 86|{% for file_format in ['FF_CSV_HEADER', 'FF_CSV_SEMICOLON_MULTIVALUE', 'FF_PARQUET', 'FF_NDJSON'] %}
 87|GRANT OWNERSHIP ON FILE FORMAT {{ fq.raw }}.{{ file_format }} TO ROLE {{ role.admin }} COPY CURRENT GRANTS;
 88|{% endfor %}
 89|
 90|-- ROUTE_SIGNALS and the automations are tasks owned by the admin role. Running
 91|-- a task needs this account-level privilege on the owner, and only ACCOUNTADMIN
 92|-- can grant it.
 93|GRANT EXECUTE TASK ON ACCOUNT TO ROLE {{ role.admin }};
 94|
 95|USE ROLE {{ role.admin }};
 96|
 97|-- --------------------------------------------------------------------------
 98|-- Database and schema usage
 99|-- --------------------------------------------------------------------------
100|{% set consumer_roles = [role.service, role.compliance_officer] + role.branch_analysts.values()|list %}
101|{% for consumer in consumer_roles %}
102|GRANT USAGE ON DATABASE {{ db }} TO ROLE {{ consumer }};
103|GRANT USAGE ON SCHEMA {{ fq.curated }} TO ROLE {{ consumer }};
104|GRANT USAGE ON SCHEMA {{ fq.governance }} TO ROLE {{ consumer }};
105|GRANT USAGE ON SCHEMA {{ fq.evidence }} TO ROLE {{ consumer }};
106|{% endfor %}
107|
108|-- --------------------------------------------------------------------------
109|-- Read access to curated and governance state.
110|--
111|-- FUTURE GRANTS cover objects created by later stages, so a new dynamic table
112|-- does not silently become invisible to the roles that need it. They apply only
113|-- to objects created AFTER the grant, so the matching ALL GRANTS below covers
114|-- anything that already exists on a re-run.
115|-- --------------------------------------------------------------------------
116|{% for consumer in consumer_roles %}
117|GRANT SELECT ON FUTURE TABLES         IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
118|GRANT SELECT ON FUTURE VIEWS          IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
119|GRANT SELECT ON FUTURE DYNAMIC TABLES IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
120|GRANT SELECT ON FUTURE TABLES         IN SCHEMA {{ fq.governance }} TO ROLE {{ consumer }};
121|GRANT SELECT ON FUTURE VIEWS          IN SCHEMA {{ fq.governance }} TO ROLE {{ consumer }};
122|GRANT SELECT ON ALL TABLES            IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
123|GRANT SELECT ON ALL VIEWS             IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
124|GRANT SELECT ON ALL DYNAMIC TABLES    IN SCHEMA {{ fq.curated }}    TO ROLE {{ consumer }};
125|GRANT SELECT ON ALL TABLES            IN SCHEMA {{ fq.governance }} TO ROLE {{ consumer }};
126|GRANT SELECT ON ALL VIEWS             IN SCHEMA {{ fq.governance }} TO ROLE {{ consumer }};
127|{% endfor %}
128|
129|-- --------------------------------------------------------------------------
130|-- Evidence chain.
131|--
132|-- Read for everyone who investigates; write ONLY for the service role, because
133|-- the chain is append-only and must be written by the pipeline rather than by
134|-- hand. Analysts deliberately get no INSERT: a human editing an evidence row
135|-- would destroy the reproducibility claim.
136|-- --------------------------------------------------------------------------
137|{% for consumer in consumer_roles %}
138|GRANT SELECT ON FUTURE TABLES IN SCHEMA {{ fq.evidence }} TO ROLE {{ consumer }};
139|GRANT SELECT ON ALL TABLES    IN SCHEMA {{ fq.evidence }} TO ROLE {{ consumer }};
140|{% endfor %}
141|
142|GRANT INSERT, UPDATE ON FUTURE TABLES IN SCHEMA {{ fq.evidence }} TO ROLE {{ role.service }};
143|GRANT INSERT, UPDATE ON ALL TABLES    IN SCHEMA {{ fq.evidence }} TO ROLE {{ role.service }};
144|
145|-- The Principal Officer's attestation is the human gate on filing. Only the
146|-- compliance role may write one; this is the maker-checker boundary expressed
147|-- as a privilege rather than as prose in a prompt.
148|GRANT USAGE ON SCHEMA {{ fq.audit }} TO ROLE {{ role.service }};
149|GRANT INSERT ON FUTURE TABLES IN SCHEMA {{ fq.audit }} TO ROLE {{ role.service }};
150|GRANT INSERT ON ALL TABLES    IN SCHEMA {{ fq.audit }} TO ROLE {{ role.service }};
151|
152|-- Compliance may read the audit trail; nobody may update or delete it.
153|GRANT USAGE ON SCHEMA {{ fq.audit }} TO ROLE {{ role.compliance_officer }};
154|GRANT SELECT ON FUTURE TABLES IN SCHEMA {{ fq.audit }} TO ROLE {{ role.compliance_officer }};
155|GRANT SELECT ON ALL TABLES    IN SCHEMA {{ fq.audit }} TO ROLE {{ role.compliance_officer }};
156|
157|-- --------------------------------------------------------------------------
158|-- GROUND_TRUTH is granted to NOBODY beyond the admin role.
159|--
160|-- This is the structural half of the label-leakage control (validation gate
161|-- V6): the agent's service role has no USAGE on the schema, so no amount of
162|-- prompt engineering can reach a label. The semantic-view check is the second
163|-- half. Enforced here rather than trusted to a YAML omission.
164|-- --------------------------------------------------------------------------
165|REVOKE ALL PRIVILEGES ON SCHEMA {{ fq.ground_truth }} FROM ROLE {{ role.service }};
166|
167|-- --------------------------------------------------------------------------
168|-- Stages
169|-- --------------------------------------------------------------------------
