"""Streaming-rehearsal helper (operator aid, not committed). Names come from conf/.

usage: rc_rehearse.py state | refresh | clear-route | resume | suspend | history
"""

import json
import sys
from pathlib import Path

from risk_copilot.config import load_settings
from risk_copilot.pipeline.load import raw_fingerprint
from risk_copilot.session import execute, open_session

REPO = Path(r"c:\Users\ASHWIN\Music\HackPrepSFCoCoCLI\RiskRemoved_Snowflake")
s = load_settings(repo_root=REPO, profile="dev")
EV = s.fq("evidence")
DT = s.fq("curated", s.dt("signals_fast").name)
STREAM = s.fq("curated", s.streams_tasks.signals_stream)
TASK = s.fq("evidence", s.streams_tasks.route_signals_task)
PROC = s.fq("evidence", s.streams_tasks.route_signals_procedure)
CHAIN = ["CASE_SIGNAL", "CASE_RECORD", "SIGNAL"]  # child first


def one(session, sql):
    return execute(session, sql)[0]


def state(session):
    out = {"fingerprint": raw_fingerprint(session, s.fq("raw"))}
    out["dt_signals"] = one(session, f"SELECT COUNT(*) FROM {DT}")[0]
    out["chain"] = {t: one(session, f"SELECT COUNT(*) FROM {EV}.{t}")[0] for t in CHAIN}
    out["stream_rows"] = one(session, f"SELECT COUNT(*) FROM {STREAM}")[0]
    out["case_status"] = {
        r[0]: r[1]
        for r in execute(session, f"SELECT status, COUNT(*) FROM {EV}.CASE_RECORD GROUP BY 1")
    }
    out["case_ids"] = [r[0] for r in execute(session, f"SELECT case_id FROM {EV}.CASE_RECORD ORDER BY 1")]
    rows = execute(session, f"SHOW TASKS LIKE '{TASK.split('.')[-1]}' IN SCHEMA {EV}")
    out["task_state"] = rows[0]["state"] if rows else None
    print(json.dumps(out, indent=1, default=str))


def refresh(session):
    print(execute(session, f"ALTER DYNAMIC TABLE {DT} REFRESH")[0])


def clear_route(session):
    execute(session, "BEGIN")
    try:
        for t in CHAIN:
            print(t, "deleted", one(session, f"DELETE FROM {EV}.{t}")[0])
        execute(session, "COMMIT")
    except Exception:
        execute(session, "ROLLBACK")
        raise
    print("route:", one(session, f"CALL {PROC}(TRUE)")[0])


def history(session):
    name = TASK.split(".")[-1]
    for r in execute(
        session,
        f"SELECT scheduled_time, state, return_value, error_message FROM TABLE("
        f"{s.db()}.INFORMATION_SCHEMA.TASK_HISTORY(TASK_NAME => '{name}', "
        "SCHEDULED_TIME_RANGE_START => DATEADD('hour', -6, CURRENT_TIMESTAMP()))) "
        "ORDER BY scheduled_time",
    ):
        print(r[0], r[1], r[2], r[3] or "")


with open_session(s, unattended=True) as session:
    cmd = sys.argv[1]
    if cmd == "state":
        state(session)
    elif cmd == "refresh":
        refresh(session)
    elif cmd == "clear-route":
        clear_route(session)
    elif cmd == "resume":
        execute(session, f"ALTER TASK {TASK} RESUME")
        state(session)
    elif cmd == "suspend":
        execute(session, f"ALTER TASK {TASK} SUSPEND")
        state(session)
    elif cmd == "history":
        history(session)

